import{Rt as e,dt as t,mt as n,n as r}from"./chunks/framework.BkIgthgQ.js";var i=JSON.parse(`{"title":"SDK 源码分支","description":"语言在 sdk/lang 干净分支。Go/PHP/Swift 源码在 *-src 加独立仓。默认分支不放语言包。","frontmatter":{"title":"SDK 源码分支","description":"语言在 sdk/lang 干净分支。Go/PHP/Swift 源码在 *-src 加独立仓。默认分支不放语言包。"},"headers":[],"relativePath":"contribute/sdk.md","filePath":"contribute/sdk.md","lastUpdated":1790057721000}`),a={name:`contribute/sdk.md`};function o(r,i,a,o,s,c){return e(),t(`div`,null,[...i[0]||=[n(`<h1 id="sdk-源码分支" tabindex="-1">SDK 源码分支 <a class="header-anchor" href="#sdk-源码分支" aria-label="Permalink to “SDK 源码分支”">​</a></h1><p>每种语言一条孤儿分支 <code>sdk/&lt;lang&gt;</code>。Go/PHP/Swift 完整源码在 <code>sdk/go-src</code>、<code>sdk/php-src</code>、<code>sdk/swift-src</code>；<code>sdk/go</code> 等仅为跳转 README。不要把语言包目录画进默认分支树。</p><p>发布坐标、独立仓步骤、以及 GitHub Actions 自动发版（Conventional Commits、<code>sdk-&lt;lang&gt;-v*</code> tag、密钥名）见仓库 <code>docs/sdk-publish.md</code>。使用者安装说明在 <a href="/api/sdk/">API → SDK</a>。不要把维护者 <code>twine</code> / <code>cargo publish</code> 或 CI 密钥写进使用者页。</p><h2 id="发版只由「合并进该分支的-pr」触发" tabindex="-1">发版只由「合并进该分支的 PR」触发 <a class="header-anchor" href="#发版只由「合并进该分支的-pr」触发" aria-label="Permalink to “发版只由「合并进该分支的 PR」触发”">​</a></h2><ul><li>每条带流水线的 <code>sdk/&lt;lang&gt;</code> 分支只在<strong>指向该分支的 PR 被合并</strong>时发版（<code>pull_request: types: [closed]</code> + <code>merged == true</code>）。直推分支、以及关闭但未合并的 PR 都不发版。</li><li>合入 <code>main</code> 与 SDK 无关；服务端发版是维护者手动的 <code>workflow_dispatch</code>，见 <a href="/contribute/release">发版与 Docker</a>。</li><li><code>sdk/c</code>、<code>sdk/cpp</code> 有自己的流水线，但<strong>不进任何 registry</strong>：发版时在 GitHub Release 附一个源码归档 zip（<code>kirivers-&lt;lang&gt;-&lt;semver&gt;.zip</code>）。</li><li><code>sdk/go</code>、<code>sdk/php</code>、<code>sdk/swift</code> 三条跳转分支<strong>没有</strong>工作流；<code>sdk/*-src</code> 的流水线在本仓也只跑测试（仓库身份不是发布仓就 <code>skip</code>），真正 tag / 发包发生在拷出去的独立仓，见 <code>docs/sdk-publish.md</code>。</li><li>更新日志同样写回各分支的 <code>CHANGELOG.md</code>（缺失即创建），不要手改。</li></ul>`,5)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};